function variant(name) { return JSON.stringify(variants[name]); }
function status(name) { return JSON.stringify(statuses[name]); }
function staticJson() { return JSON.stringify(staticData); }
function collector(name) { return name in collectors ? JSON.stringify(collectors[name]) : ""; }
function collectorSettings(name) { return JSON.stringify(collectorSettingsData[name] || {}); }
